"""Write the complete empirical report from finished and verified exports."""
from pathlib import Path
import json
import sys
sys.dont_write_bytecode = True
import pandas as pd
OUT = Path(__file__).resolve().parent
POLICIES = ['source_maximin', 'source_mean_bottleneck', 'full_graph_shortest']

def read(name):
    return pd.read_csv(OUT / name, float_precision='round_trip', low_memory=False)

def main():
    census = json.loads((OUT / 'design_census.json').read_text(encoding='utf-8'))
    run = json.loads((OUT / 'run_summary.json').read_text(encoding='utf-8'))
    verify = json.loads((OUT / 'independent_verification.json').read_text(encoding='utf-8'))
    raw = json.loads((OUT / 'measured_witness_raw_verification.json').read_text(encoding='utf-8'))
    self_test = json.loads((OUT / 'qa/self_test_verification.json').read_text(encoding='utf-8'))
    assert verify['status'] == raw['status'] == self_test['status'] == 'passed'
    ag = read('complete_heldout_statistics.csv.gz')
    weights = read('continuous_and_threshold_weighting_summary.csv')
    diagnostics = read('intrinsic_selection_topology_weighting_summary.csv')
    coverage = read('coverage_and_reuse.csv').set_index('stratum')
    classes = read('complete_18_class_statistics.csv')
    witness = json.loads((OUT / 'measured_witness.json').read_text(encoding='utf-8'))
    all_coverage = coverage.loc['all_holdouts']
    source_route = witness['routes']['source_maximin']
    alternative_route = witness['routes']['full_graph_shortest']
    assert (witness['molecule_a'], witness['molecule_b']) == ('C#Cc1cccc(N)c1', 'CSc1cccc(N)c1')
    assert witness['partners'][witness['heldout_position']] == 'Cc1cc(C(=O)O)cc(Cl)n1'
    assert {partner for i, partner in enumerate(witness['partners']) if i != witness['heldout_position']} == {'O=C(O)COc1ccccc1', 'O=C(O)c1ccc(C(F)(F)F)cn1'}
    assert source_route['target_bottleneck'] == witness['best_target_at_source_optimum_evaluation_only'] == 0
    assert abs(alternative_route['joint_bottleneck'] - witness['union_oracle']) < 1e-12
    assert source_route['recipe_route'] == witness['routes']['source_mean_bottleneck']['recipe_route']
    connected = int(ag.n_connected_source_endpoint_pairs.sum())
    sourcefail = int(ag.n_source_route_failed20.sum())
    targetendpoint = int(ag.n_source_feasible_target_endpoint_failures20.sum())
    targetinternal = int(ag.n_source_feasible_target_own_internal_failures20.sum())
    intrinsicfail = int(ag.n_separately_feasible_shared_impossible20.sum())
    unionfeasible = int(ag.n_union_route_feasible20.sum())
    assert connected == sourcefail + targetendpoint + targetinternal + intrinsicfail + unionfeasible

    def value(stratum, unit, policy, metric):
        return float(weights[(weights.stratum == stratum) & (weights.weighting_unit == unit) & (weights.policy == policy) & (weights.metric == metric)].value.iloc[0])

    def diag(stratum, topology, unit, metric):
        return float(diagnostics[(diagnostics.stratum == stratum) & (diagnostics.endpoint_topology == topology) & (diagnostics.weighting_unit == unit) & (diagnostics.metric == metric)].value.iloc[0])
    lines = ['# Can source-partner routes share their scope with a held-out molecular context?', '', 'Date: 2026-10-17.', '', 'This analysis implements the source-partner-frozen route test left open in R27. It retains the same exact A/B molecular pair and holds out both A+P and B+P for one actual partner, choosing a route from the other two partner bundles only. It evaluates molecular-context scope under component substitution; it does not establish a prospective recommendation method, an unseen-edit or scaffold generalization result, or a molecular mechanism.', '', f'The measured boundary separates endpoint compatibility from route organization: among {int(ag.n_source_route_feasible20.sum()):,} source-feasible views, {targetendpoint:,} fail at a held-out endpoint, {targetinternal:,} have high held-out endpoints but no held-out own high route, and {intrinsicfail:,} are separately feasible but lack a shared six-target route. A further {int(ag.source_maximin_n_avoidable_selection_failure20.sum()):,} views have a shared high route that the frozen source-maximin policy misses. Thus endpoints, target-internal organization, collective compatibility and frozen selection have distinct measured denominators.', '', '## Complete Opportunity Frame', '', f"All {census['n_triples']:,} R27 coherent triple acquisition assignments yield {census['n_holdouts']:,} held-out evaluations. The parent inventory retains {census['n_parent_focal_keys']:,} exact-pair keys; the complete held-out frame covers {int(all_coverage.n_focal_keys):,} focal keys ({int(all_coverage.n_global_exact_pairs):,} global exact pairs), with the complete 20-dataset/18-class inventory retained in the exports. There are {census['n_source_defined_endpoint_pairs']:,} source-defined high 20% endpoint pairs, including {census['n_source_defined_endpoint_pairs'] - connected:,} full-graph-disconnected pairs, and {connected:,} connected pairs. Endpoint membership uses the four source targets only; low held-out endpoints are retained.", '', '| Held-out support status | Assignments |', '|---|---:|']
    for status, n in census['holdout_support_status'].items():
        lines.append(f'| {status} | {n:,} |')
    cc = coverage.loc['connected']
    lines += ['', f"Connected rows cover {int(cc.n_focal_keys)} focal keys, {int(cc.n_global_exact_pairs)} global exact molecular pairs and {int(cc.n_reaction_classes)} reaction classes. Acylation supplies {int(classes.set_index('rxn_class').loc['Acylation', 'n_connected_source_endpoint_pairs']):,}/{connected:,} connected views. The complete inventory retains the remaining classes with zero conditional opportunities. See `coverage_and_reuse.csv`, `complete_470_focal_key_statistics.csv.gz`, `complete_20_dataset_statistics.csv`, and `complete_18_class_statistics.csv`.", '', '## Frozen Source Policies', '', 'The whole-triple graph is fixed by availability of all six targets, with an edge for exactly one changed condition-slot token, including identity and dose. Routes compare independently measured recipes and are not serial reaction protocols. A source-high endpoint has minimum measured yield>=20% across the four source targets. The primary policy maximizes the source minimum along the route. Baselines maximize the route bottleneck of the arithmetic mean of the four source yields, or choose the shortest whole-graph route. Every policy then uses shortest length and lexical recipe-ID order where applicable. No held-out yield selects endpoints, routes, tie-breaks or hyperparameters. All policies use exactly the same rows, including source failures.', '', 'A disconnected row has no route and its continuous outcome is undefined. Reported continuous route means condition on connected rows. Zero-opportunity keys/classes remain present, with no fabricated conditional means. `shortest_tie` detects multiple shortest source-objective-optimal routes, not all longer optimal routes. The frozen policy never substitutes a target-optimal tie member.', '', f'There are {int(ag.source_maximin_n_shortest_tie.sum()):,} connected maximin rows with multiple shortest source-optimal routes. The lexical tie rule is source-only and deterministic, but it is one policy choice; losses at other tied routes are not automatically identical. The claim that every source-optimal tie fails is established only for the explanatory witness below, not for every failure in the census.', '', '## Separate Failure Sources', '', 'The first five rows partition all connected source-selected endpoint views at 20%. The final three rows are policy-specific failure subsets of the union-feasible group and are not added to that partition.', '', '| Category | Endpoint views |', '|---|---:|', f'| Source joint route itself infeasible | {sourcefail:,} |', f'| Source feasible; held-out endpoint failure | {targetendpoint:,} |', f'| Source feasible; held-out endpoints high but held-out own route infeasible | {targetinternal:,} |', f'| Source and held-out each separately feasible; full-six-target shared route infeasible | {intrinsicfail:,} |', f'| Full-six-target oracle feasible | {unionfeasible:,} |']
    for p in POLICIES:
        lines.append(f"| Union feasible; {p} selection fails | {int(ag[p + '_n_avoidable_selection_failure20'].sum()):,} |")
    lines += ['', 'The strict intrinsic incompatibility row requires both source and held-out own routes to exist. The broader endpoint-export flag `shared_route_impossible20` also includes target-own internal failure and must not be substituted for that strict row. Target internal failure along the selected route despite an available target-only route is a separate diagnostic; its full counts are exported, including cases where the six-target union is inherently impossible.', '', '## Continuous Achieved Scope And Oracle Gap', '', 'For a frozen selected route, J is the minimum across all six targets on that route. Selection loss is K_union-J, with K_union the full-six-target oracle on the identical graph and endpoints. Intrinsic continuous incompatibility is min(K_source,K_target)-K_union. Their sum is min(K_source,K_target)-J. These are evaluation-only oracles.', '', '| Connected-row weighting | Active units | Maximin J (%) | Mean-objective J (%) | Shortest J (%) | Maximin union gap (pp) |', '|---|---:|---:|---:|---:|---:|']
    for unit in ['endpoint', 'heldout', 'focal_key', 'global_exact_molecular_pair', 'dataset', 'reaction_class']:
        pp = weights[(weights.stratum == 'connected') & (weights.weighting_unit == unit)]
        n = connected if unit == 'endpoint' else int(pp.n_active_units.iloc[0])
        jj = [100 * value('connected', unit, p, 'joint') for p in POLICIES]
        lines.append(f"| {unit} | {n:,} | {jj[0]:.5f} | {jj[1]:.5f} | {jj[2]:.5f} | {100 * value('connected', unit, POLICIES[0], 'union_gap'):.5f} |")
    lines += ['', 'Macro means first pool endpoints within each active unit, then weight active units equally. They are descriptive reuse weights, not independent-sample estimates or inferential confidence intervals. The exact-pair-key unit retains dataset/role; the global-pair unit combines keys for the same exact molecular pair.', '', '| Conditional stratum | Policy | Denominator | Achieved J (%) | Union gap (pp) | Success20 (%) | Source failure20 (%) |', '|---|---|---:|---:|---:|---:|---:|']
    for stratum in ['connected', 'source_feasible', 'source_and_target_separately_feasible', 'union_feasible']:
        den = int(weights[(weights.stratum == stratum) & (weights.weighting_unit == 'endpoint')].endpoint_denominator.iloc[0])
        for p in POLICIES:
            lines.append(f"| {stratum} | {p} | {den:,} | {100 * value(stratum, 'endpoint', p, 'joint'):.5f} | {100 * value(stratum, 'endpoint', p, 'union_gap'):.5f} | {100 * value(stratum, 'endpoint', p, 'success20'):.4f} | {100 * value(stratum, 'endpoint', p, 'source_failure20'):.4f} |")
    lines += ['', 'Target/oracle-defined conditional strata are retrospective diagnostics applied after freezing the policy. The complete table also retains source-feasible/high-held-out-endpoint conditioning and every macro weight.', '', '## Endpoint Topology And Intrinsic Decomposition', '', '| Connected source-selected topology | Views | Intrinsic gap (pp) | Maximin selection gap (pp) | Maximin J (%) |', '|---|---:|---:|---:|---:|']
    for topology in ['all', 'adjacent', 'nonadjacent']:
        pp = diagnostics[(diagnostics.stratum == 'all_connected_source_selected') & (diagnostics.endpoint_topology == topology) & (diagnostics.weighting_unit == 'endpoint')]
        n = int(pp.n_endpoint_views.iloc[0])
        lines.append(f"| {topology} | {n:,} | {100 * diag('all_connected_source_selected', topology, 'endpoint', 'intrinsic_gap_sum'):.6f} | {100 * diag('all_connected_source_selected', topology, 'endpoint', 'source_maximin_selection_gap_sum'):.6f} | {100 * diag('all_connected_source_selected', topology, 'endpoint', 'source_maximin_joint_sum'):.5f} |")
    lines += ['', 'Adjacent endpoints have a direct source-optimal route consisting only of the two endpoints; their maximin selection gap is structurally zero. Nonadjacent denominators and conditional/macro tables are provided in `intrinsic_selection_topology_weighting_summary.csv`. Neither a large extreme loss nor an endpoint-weighted gain alone describes all classes.', '', '## Measured Molecular Witness', '', f"Posthoc pilot witness {witness['group_id']} retains aniline pair `{witness['molecule_a']}` / `{witness['molecule_b']}`. The held-out acid is `{witness['partners'][witness['heldout_position']]}`; source acids are " + ' and '.join((f'`{partner}`' for i, partner in enumerate(witness['partners']) if i != witness['heldout_position'])) + f". All calculations use the full {witness['n_nodes']}-node/{witness['n_edges']}-edge measured graph, with endpoints DCC/HOAT and EDC-HCl/ethyl cyanoglyoxylate-2-oxime.", '', f"The frozen source-maximin route changes additive first through DCC/ethyl cyanoglyoxylate-2-oxime. Its source bottleneck is {100 * source_route['source_bottleneck']:.5f}%, but held-out A has an actual measured zero at the internal recipe, giving joint {100 * source_route['joint_bottleneck']:.5f}%. The alternative changes coupling reagent first through EDC-HCl/HOAT: source {100 * alternative_route['source_bottleneck']:.5f}%, held-out {100 * alternative_route['target_bottleneck']:.5f}%, joint {100 * alternative_route['joint_bottleneck']:.5f}%, which equals the full-graph union oracle. The held-out own optimum is {100 * witness['target_optimum']:.5f}%, and both held-out endpoints are >={100 * witness['target_endpoint_minimum']:.5f}%.", '', f"An evaluation-only complete-graph bound gives best held-out bottleneck {100 * witness['best_target_at_source_optimum_evaluation_only']:.5f}% among all source-optimal routes. Thus this witness is not repaired by a favorable source-optimal tie: recovering the held-out partner requires a source sacrifice. The shortest-graph baseline happens to choose the successful {alternative_route['n_edges']}-edge route; both frozen source objectives choose the failed {source_route['n_edges']}-edge route. This is an explanatory counterexample to universal source-maximin portability, not proof that shortest routes are generally superior.", '', f"Raw readback verified {raw['n_raw_reaction_records']} original reaction rows and {raw['n_raw_condition_rows']} original condition rows, reconstructing every witness node-target mean. The reaction data contain {raw['n_exact_zero_raw_reactions']} exact measured zeros. All reagent identities/doses, solvent, temperature and time agree with the original condition workbook. Original files were read-only and hashed. The pilot witness was selected from the first 500 triples after observing evaluation loss and is not a representative prevalence estimate.", '', '## Verification And Limits', '', f"The independent verifier checked all {verify['n_endpoint_rows_capacity_and_flag_checked']:,} endpoint memberships, source/target/union capacities, flags and conditional sums using descending-edge maximum-spanning forests; the generator uses max-min Floyd closure. It independently reconstructed {verify['n_deterministically_stratified_routes_checked']:,} deterministically stratified routes with reverse-distance lexical paths across every active heldout. Maximum capacity/route difference was {verify['maximum_absolute_capacity_or_route_error']:.3g}. This does not claim independent path reconstruction for every policy on every endpoint. A separate {self_test['n_all_pair_route_reconstructions']:,} all-pair reconstruction selfcheck passed.", '', 'The graph is conditioned on held-out measurement availability, though not held-out yields. Missing recipes outside this common measured support may change conclusions if subsequently measured. Acquisition assignments, source contexts, exact molecular pairs, endpoints and raw measurements are repeatedly reused. Outcomes are retrospective for measured partners of the same exact pair; there is no held-out edit/scaffold, random prospective experiment, causal partner intervention, or prospective recommendation validation. Sparse class strata and zero-opportunity strata are retained. Threshold 20% and all policy/tie rules were fixed without target tuning.', '', 'Reproduction from source: run `analyze_heldout_routes.py --limit 500` to regenerate the fixed pilot witness-selection input; then run `analyze_heldout_routes.py` for the complete frame, `export_measured_witness.py`, `finalize_metadata.py`, `summarize_diagnostics.py`, `verify_with_self_test.py`, `build_report.py`, and `make_delivery_manifest.py`, in that order, using the bundled Python. The primary complete run took ' + f"{run['seconds'] / 60:.2f} minutes. The default verifier wrapper runs the independent check and the all-pair algorithm selfcheck, recording the actual selfcheck count in `qa/self_test_verification.json`. See `ANALYSIS_CONTRACT.md`, source manifests and verification JSON files. All new files are confined to this directory; raw data were not modified.", '']
    (OUT / 'ROUND28_HELDOUT_ROUTE_SCOPE_REPORT.md').write_text('\n'.join(lines), encoding='utf-8')
    print('REPORT', len(lines), 'lines', flush=True)
if __name__ == '__main__':
    main()
